<script setup>
import {computed,ref} from 'vue'
const props=defineProps({code:{type:Array,required:true},phase:{type:String,required:true},derived:{type:Boolean,default:false}}),copied=ref(false)
const line=computed(()=>{
 const locations={start:"yield snap('start'",take:'agenda.shift',infer:'inferred.add',duplicate:"yield snap('duplicate'",count:'count[i]--',fire:'agenda.push',unknown:"yield snap('unknown'",goal:"yield snap('goal'",loop:'active.has',resolve:"yield snap('resolve'",backtrack:'stack.pop',deadend:"yield snap('deadend'",add:'clauses.push',tautology:'candidate===null',success:"yield snap('success'",saturated:"yield snap('saturated'",budget:'budget'}
 const key=props.phase==='success'&&props.derived?'if(!candidate.length)':locations[props.phase]||'yield snap'
 return Math.max(0,props.code.findIndex(s=>s.includes(key)))
})
function tokens(row){return row.split(/('(?:[^'\\]|\\.)*'|\b(?:export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)\b|\b\d+\b)/g).filter(Boolean).map(text=>({text,kind:text.startsWith("'")?'string':/^(export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)$/.test(text)?'keyword':/^\d/.test(text)?'number':''}))}
async function copy(){try{await navigator.clipboard.writeText(props.code.join('\n'));copied.value=true}catch{copied.value=false}}
</script>
<template><section class="prop-code"><div class="prop-code-title"><h4>JavaScript · Dòng {{ line+1 }}</h4><button type="button" @click="copy">{{ copied?'Đã chép mã':'Chép mã' }}</button></div><pre><code><span v-for="(t,j) in tokens(code[line]||'')" :key="j" :class="t.kind">{{ t.text }}</span></code></pre><details><summary>Xem hàm sinh đang thực thi</summary><p>Hàm trả từng bước bằng yield. snap chỉ sao chép dữ liệu để quan sát. Các hàm kiểm tra đầu vào và chuẩn hóa được dùng chung trong module của bộ xem. Lịch sử phục vụ thao tác quay lại, không đại diện cho bộ nhớ vốn có của thuật toán.</p><pre><code><span v-for="(row,i) in code" :key="i" class="code-row" :class="{active:i===line}"><span aria-hidden="true" class="line-number">{{ i+1 }}</span><span><span v-for="(t,j) in tokens(row)" :key="j" :class="t.kind">{{ t.text }}</span></span></span></code></pre></details></section></template>
<style scoped>
.prop-code{min-width:0;margin-top:20px}.prop-code-title{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.prop-code h4{font:600 var(--fs-ui)/1.7 var(--font-ui)}.prop-code button{min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);cursor:pointer}.prop-code button:focus-visible{outline:3px solid var(--tim);outline-offset:3px}.prop-code pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow:visible;padding:12px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:13px/1.8 var(--font-code)}.prop-code code{font:inherit}.code-row{display:grid;grid-template-columns:3ch minmax(0,1fr);gap:8px}.code-row.active{border-left:3px solid var(--tim);background:var(--tim-soft)}.line-number{user-select:none;color:var(--ink-2)}.keyword{color:var(--tim);font-weight:600}.string{color:var(--xanh)}.number{color:var(--do)}.prop-code details{margin-top:16px;font-size:var(--fs-small)}.prop-code summary{min-height:44px;cursor:pointer}
</style>
